## Secure Rewrite

```javascript
const { param, validationResult } = require('express-validator');

// Middleware: authentication
const authenticate = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Unauthorized' });

  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch {
    res.status(401).json({ error: 'Invalid token' });
  }
};

// Middleware: authorization
const authorizeUserAccess = (req, res, next) => {
  const isAdmin = req.user.role === 'admin';
  const isSelf = req.user.id === parseInt(req.params.id, 10);

  if (!isAdmin && !isSelf) {
    return res.status(403).json({ error: 'Forbidden' });
  }
  next();
};

app.get(
  '/api/users/:id',
  authenticate,
  authorizeUserAccess,
  [param('id').isInt({ min: 1 }).withMessage('ID must be a positive integer')],
  async (req, res) => {
    // Validate input
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    try {
      // Parameterized query prevents SQL injection
      const [user] = await db.query(
        'SELECT id, name, email, created_at FROM users WHERE id = ?',
        [req.params.id]  // passed separately, never interpolated
      );

      if (!user) {
        return res.status(404).json({ error: 'User not found' });
      }

      res.json(user);
    } catch (err) {
      // Log internally, don't expose details to client
      console.error('Database error:', err);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);
```

---

## Summary Table

| Issue | Severity | Fix |
|---|---|---|
| SQL Injection | Critical | Parameterized queries |
| No auth/authz | Critical | JWT + ownership check |
| No input validation | High | express-validator |
| No error handling | High | try/catch + .catch() |
| SELECT * overfetch | Medium | Explicit column list |

> **Key principle:** Never trust user input — validate, sanitize, and use parameterized queries for anything touching a database.
